class Boundary extends React.Component<{fallback: React.ReactNode; name: string}, {err?: Error}> {
  state = {} as {err?: Error};
  static getDerivedStateFromError(err: Error) { return { err }; }
  componentDidCatch(err: Error, info: React.ErrorInfo) {
    Sentry.captureException(err, { tags: { widget: this.props.name }, extra: info });
  }
  render() { return this.state.err ? this.props.fallback : this.props.children; }
}
